import React from 'react';
import { ChevronRight } from 'lucide-react';
import { acct } from '../format.js';

const KIND = { transaction: 'Transaction', service_charge: 'Service Charge', interest: 'Interest Earned' };

/** Read-only view of the general ledger lines generated by a transaction. */
export default function GlEntries({ gl }) {
  if (!gl?.length) return null;
  const dr = gl.reduce((s, g) => s + Number(g.debit), 0);
  const cr = gl.reduce((s, g) => s + Number(g.credit), 0);
  const kinds = new Set(gl.map((g) => g.entry_kind));
  return (
    <details className="gl-entries">
      <summary><ChevronRight size={18} className="gl-caret" aria-hidden="true" />General ledger entries</summary>
      <table className="table compact">
        <thead><tr>{kinds.size > 1 && <th>Entry</th>}<th>Account</th><th>Fund</th><th className="num">Debit</th><th className="num">Credit</th></tr></thead>
        <tbody>
          {gl.map((g, i) => (
            <tr key={i}>
              {kinds.size > 1 && <td>{KIND[g.entry_kind]}</td>}
              <td>{g.account_number ? `${g.account_number} · ` : ''}{g.account_name}</td>
              <td>{g.fund_name || <span className="muted">—</span>}</td>
              <td className="num">{Number(g.debit) ? acct(g.debit) : ''}</td>
              <td className="num">{Number(g.credit) ? acct(g.credit) : ''}</td>
            </tr>
          ))}
        </tbody>
        <tfoot><tr><td colSpan={kinds.size > 1 ? 3 : 2}>Totals</td><td className="num">{acct(dr)}</td><td className="num">{acct(cr)}</td></tr></tfoot>
      </table>
    </details>
  );
}
